["menu_feature_blackmarket_rename_desc"] = "GÖNDEREN: BAIN [BAİN@///REDACTED///]$NL;ALICI: $player;$NL;TARİH: 2014-04-24 09:45 (GMT+1)$NL;KONU: ENVANTER DÜZENLEME VE YENİDEN ADLANDIRMA GÜNCELLEMESİ$NL;$NL;SELAM $player;. KESKİN NİŞANCI TÜFEKLERİ VE ALTIN AK.762 TÜFEĞİNİN GELİŞİYLE, DEĞERLİ CEPHANELİĞİNİ DAHA İYİ DÜZENLEYİP SERGİLEMENE YARDIM EDECEK BİRKAÇ YENİ ÖZELLİK SUNMAK İSTEDİM.$NL;$NL;ARTIK SİLAHLARINI VE MASKELERİNİ TAŞIYIP YERLERİNİ DEĞİŞTİREBİLİRSİN. UYGUN BİR EŞYAYI SEÇİP KUŞAN, ARDINDAN ÇIKAN TAŞIMA DÜĞMESİNE TIKLA VE TAŞIMAK İSTEDİĞİN YERDE YERLEŞTİRME DÜĞMESİNİ KULLAN. DOLU BİR YUVA SEÇERSEN EŞYALARIN YERLERİ DEĞİŞİR.$NL;$NL;ARTIK SİLAHLARI VE MASKELERİ YENİDEN ADLANDIRABİLİRSİN. SİLAHIN VEYA MASKENİN ADINA TIKLA VE SANA ÖZEL BİR İSİM VER.$NL;$NL;(NOT: SEÇTİĞİN ADLARI SENDEN BAŞKA KİMSE GÖREMEZ.)$NL;$NL;- BAIN",
["menu_feature_crimenet_thanks_gagemod"] = "YENİ BİR MESAJIN VAR",
["menu_feature_crimenet_thanks_gagemod_desc"] = "GÖNDEREN: GAGE [GAGE@///REDACTED///]$NL;ALICI: $player;$NL;TARİH: 2014-04-10 17:02 (GMT+1)$NL;KONU: AKILLICA BİR HAMLE.$NL;$NL;SELAM $player;, GAGE MOD COURIER DLC PAKETİNİ SATIN ALDIĞIN İÇİN SANA TEŞEKKÜR ETMEK İSTEDİM.$NL;$NL; MOD COURİER İŞİ HAKKINDA DAHA FAZLA BİLGİ EDİNMEK VE İLERLEMENİ GÖRMEK İÇİN CRIME.NET’TEKİ GAGE SİMGESİNİ SEÇMEN YETERLİ (KOCAMAN BİR \"G\", GÖZÜNDEN KAÇMAZ).$NL;$NL;- GAGE$NL;",
["menu_feature_crimenet_welcome_desc"] = "GÖNDEREN: BAIN [BAİN@///REDACTED///]$NL;ALICI: $player;$NL;TARİH: 2013-08-13 00:02 (GMT+1)$NL;KONU: CRIME.NET’E HOŞ GELDİN$NL;$NL;SELAM $player;, CRIME.NET’E HOŞ GELDİN.$NL;$NL;BUNU OKUYORSAN ÖRGÜTÜMÜZÜN MERKEZİNE ERİŞİMİN ONAYLANMIŞ DEMEKTİR. TEBRİKLER; DAHA BÜYÜK BİR DÜNYAYA İLK ADIMINI ATTIN.$NL;$NL;CRIME.NET’İN TEMEL İŞLEVLERİNE BİR GÖZ ATALIM. BAŞTA KARMAŞIK GÖRÜNÜRSE ENDİŞELENME; HER ŞEY AŞAĞI YUKARI KENDİNİ AÇIKLIYOR.$NL;$NL;• CRIME.NET$NL;BURADA YENİ İŞLER BULABİLİR, BAŞKA EKİPLERLE BULUŞABİLİR, BAĞLANTILARIN HAKKINDA DAHA FAZLA BİLGİ EDİNEBİLİR VE ARADA SIRADA BİNBİR EMEKLE KAZANDIĞIN DENİZAŞIRI PARANIN BİR KISMINI KUMARDA KAYBEDEBİLİRSİN.$NL;$NL;• SÖZLEŞMEYE EV SAHİPLİĞİ YAPMAK$NL;ÜZERİNDE SAYAÇ OLAN İŞLERE SEN EV SAHİPLİĞİ YAPARSIN. SAYAÇ SIFIRA ULAŞTIĞINDA O SÖZLEŞME KAYBOLUR VE CRIME.NET YENİSİNİ OLUŞTURUR. EV SAHİPLİĞİ HAKKINDA BİR NOT: SÖZLEŞMENİN BAŞINDA SEN VARSIN VE EKİBİNDEN SEN SORUMLUSUN. $NL;$NL;AYRILIRSAN TÜM EKİP KAYBEDER. HERKESİ HAYATTA TUTMAYA ÇALIŞ VE HERKESİN PAYDAY’E ULAŞMASINI SAĞLA.$NL;$NL;• SÖZLEŞMEYE KATILMAK$NL;BAŞKASININ EV SAHİPLİĞİ YAPTIĞI İŞLERDE SAYAÇ YERİNE DÖRT ADAMLI BİR SİMGE BULUNUR. EV SAHİBİNİN ADI MAVİ, ARKADAŞINSA YEŞİL GÖRÜNÜR. EN AZ BİR BOŞ YER OLDUĞU SÜRECE EKİBE KATILABİLİRSİN.$NL;$NL;• ZORLUK$NL;ZORLUK, SIFIR İLE DÖRT KAFATASI ARASINDA GÖSTERİLİR. KAFATASI SAYISI ARTTIKÇA İŞ ZORLAŞIR. İLK KEZ OYNUYORSAN KAFATASI OLMAYAN BİR İŞ SEÇ. BANA GÜVEN. DÖRT KAFATASINA DEATH WISH DİYORUZ; EN AZ 50. SEVİYEYE GELMEDEN BUNA KALKIŞMAMALISIN BİLE.$NL;$NL;• ÖDÜLLER$NL;BİR SÖZLEŞMEYİ BAŞARIYLA TAMAMLAMAK SANA PARA VE DENEYİM KAZANDIRIR. TABAN ÖDEMEYİ GÖRMEK İÇİN İMLECİ SÖZLEŞME İŞARETİNİN ÜZERİNE GETİR. AMA SON KAZANCIN ÇOK DAHA BÜYÜK OLABİLİR; RİSK BONUSLARI VAR VE SOYGUN SIRASINDA EK PARA ELDE EDEBİLİRSİN. UNUTMA: ELİNE GEÇİREBİLDİĞİN HER ŞEY KÂRDIR.$NL;$NL;PARA VE DP, SÖZLEŞMENİN HER GÜNÜ TAMAMLANDIĞINDA VERİLİR. $NL;$NL;SÖZLEŞMENİN TAMAMINI BİTİRDİĞİNDE PAYDAY DEDİĞİMİZ AŞAMAYA DA GELİRSİN: RASTGELE BİR EŞYANIN KİLİDİNİ AÇMAK İÇİN BİR KART ÇEKERSİN. NADİR MASKELERİ, SİLAH MODİFİKASYONLARINI VE BAŞKA FAYDALI ŞEYLERİ BÖYLE KAZANIRSIN. $NL;$NL;• SÖZLEŞME SÜRESİ$NL;İŞLERİN SÜRELERİ FARKLIDIR. UZUN SOYGUNLARA GEÇMEDEN ÖNCE BİRKAÇ 1 GÜNLÜK İŞLE BAŞLA. DP ÖDÜLÜ SEVİYENE GÖRE ÖLÇEKLENİR; BU YÜZDEN BAŞLANGIÇTA BOYUNU AŞAN BİR İŞTE KENDİNİ PARÇALAMANA GEREK YOK.$NL;$NL;$NL;BİRAZ DAHA KARMAŞIK KONULAR$NL;$NL;• FİLTRELER$NL;CRIME.NET’TE GÖSTERİLENLERİ AYARLAMAK İÇİN ÇEŞİTLİ FİLTRELER VAR. ÖRNEĞİN YALNIZCA ARKADAŞLARINI ARAYABİLİR, ARAMA ALANINI GENİŞLETEBİLİR VEYA BELİRLİ BİR İŞİ ARAYABİLİRSİN. UMARIM NE İŞE YARADIKLARI AÇIKTIR.$NL;$NL;• GİZLİLİK$NL;SÖZLEŞME İŞARETİNİN YANINDA KÜÇÜK BİR HAYALET SİMGESİ GÖRÜRSEN İŞ ALARM VERİLMEDEN TAMAMLANABİLİR DEMEKTİR. BİR İŞİ GİZLİCE BİTİRMEK, HEMEN ARDINDAN ALACAĞIN SÖZLEŞMEDE GEÇERLİ OLACAK BİR DP BONUSU KAZANDIRIR. BİR TAVSİYE: YENİYSEN ŞİMDİLİK GİZLİLİĞİ KAFANA TAKMA. TERTEMİZ BİR GİZLİ İŞ ÇIKARMAK İÇİN UYUMLU BİR EKİP VE CİDDİ BECERİ GEREKİR.$NL;$NL;• BONUS SİSTEMİ$NL;AYNI İŞİ TEKRAR TEKRAR YAPARSAN O SÖZLEŞMEDEN KAZANDIĞIN DP AZALMAYA, DİĞERLERİNİNKİ ARTMAYA BAŞLAR. EN FAZLA DP’Yİ KAZANMANIN PÜF NOKTASI FARKLI FARKLI İŞLER YAPMAKTIR. AZALAN DP, EKSİ İŞARETLERİ VE KIRMIZI BİR PARILTIYLA; ARTAN DP İSE ARTI İŞARETLERİ VE TURUNCU BİR PARILTIYLA GÖSTERİLİR.$NL;$NL;• SÖZLEŞME ARACISI$NL;BİRAZ PARA BİRİKTİRİP SEVİYE ATLAMAYA BAŞLADIĞINDA SÖZLEŞME ARACISINI ZİYARET EDEREK HANGİ İŞLERİ YAPMAK İSTEDİĞİNİ SEÇEBİLİRSİN. YİNE DE İLK KEZ OYNUYORSAN ŞİMDİLİK SUNULAN SÖZLEŞMELERLE DEVAM ET.$NL;$NL;KISACA:$NL;CRIME.NET’İ KULLANARAK İŞ BUL, PARA KAZAN VE O BÜYÜK PAYDAY’E ULAŞ.$NL;$NL;ŞİMDİLİK BİLMEN GEREKENLER BUNLAR. SUÇ DÜNYASINDA BİRKAÇ BASAMAK YÜKSELDİĞİNDE SANA BİR NOT DAHA GÖNDERİP DAHA KARMAŞIK KONULARI ANLATIRIM. BOL ŞANS.$NL;$NL;- BAIN$NL;",
