["menu_fullscreen_help"] = "TAM EKRANI AÇ VEYA KAPAT. TAM EKRAN MODU PERFORMANSI EN İYİ DURUMA GETİRİR. PENCERE MODU AYNI ANDA BAŞKA İŞLER YAPMANI SAĞLAR.",
["menu_gage_assignment_div_menu"] = "MENÜ",
["menu_gage_assignment_div_packages"] = "PAKETLER",
["menu_gage_assignment_introduction_desc"] = "ÖNCELİKLE KURYE GÖREVİNİ ÜSTLENDİĞİN İÇİN TEŞEKKÜRLER. ARTIK ESKİSİ KADAR KOŞTURAMIYORUM. İŞ ŞÖYLE: D.C.’NİN DÖRT BİR YANINA DAĞILMIŞ PAKETLER VAR. BUNLARI TAŞIMAK İÇİN PEK ÇOK İNSAN TUTUYORUM AMA KİMSE BİR PAKETİ YOLUN TAMAMI BOYUNCA TAŞIMIYOR. BU PEK GÜVENLİ OLMAZDI. SENİN İŞİN, GÖRDÜĞÜN PAKETLERİ ALIP BANA GETİRMEK. YETERİNCE PAKET GETİRİRSEN SANA BEDAVA EŞYA VERİRİM.$NL;$NL;DEĞERLERİNE GÖRE RENKLERLE KODLANMIŞ 5 PAKET TÜRÜ VAR: GREEN MANTİS, YELLOW BULL, RED SPİDER, BLUE EAGLE VE PURPLE SNAKE. YEŞİL TEMEL MALZEMELER, MOR İSE ÇOK ARANAN MALLAR. ANLADIN SEN.$NL;$NL;BİR PAKET GÖRDÜĞÜNDE YANINA GİDİP ALMAN YETERLİ. HER GÜNÜN SONUNDA PAKETLERİ KAZANIRSIN. PAKET SAYISI TÜM EKİBE YAZILIR; YANİ EKİP ARKADAŞLARININ ÖNÜNDEN GANİMET KAPMANA GEREK YOK. BELİRLİ BİR RENKTEN YETERİNCE PAKET TOPLADIĞINDA ÖDÜLLER ÜCRETSİZ OLARAK OTOMATİK BİÇİMDE ENVANTERİNE EKLENİR. ÖDÜL PAKETİNDEKİ TÜM MODİFİKASYONLARDAN BİRER TANE ALIRSIN. AYRINTILAR İÇİN PAKET SAYFALARINA BAK.$NL;$NL;BİR PAKETİ TAMAMLADIKTAN SONRA YENİDEN TOPLAMAYA BAŞLAYABİLİRSİN. EVE PAKET GETİRDİKÇE DAHA FAZLA ÖDÜL KAZANMAYA DEVAM EDERSİN. İYİ AVLAR.$NL;$NL;- GAGE.",
["menu_gage_assignment_introduction_title"] = "KURYE GÖREVİ",
["menu_gage_assignment_summary_desc"] = "ARADIĞIN BEŞ PAKET TÜRÜ BUNLAR. İLERLEMENE BAKMAK İSTEDİĞİNDE BURAYA DÖNEBİLİRSİN.$NL;$NL;PAKET TESLİMATLARINI İSTEDİĞİN KADAR TAMAMLAYABİLECEĞİNİ UNUTMA. HER TESLİMATI BİTİRDİĞİNDE ÖDÜL EŞYALARINDAN YENİ BİR SET OTOMATİK OLARAK ENVANTERİNE AKTARILIR. BELİRLİ ÖDÜLLERİN LİSTESİ İÇİN PAKETLERİN KENDİ SAYFALARINA BAK.",
