["menu_st_skilltree"] = "BECERİLER",
["menu_st_spec_1"] = "EKİP LİDERİ",
["menu_st_spec_10"] = "KUMARBAZ",
["menu_st_spec_10_desc"] = "SAVAŞIN ATEŞİNE ATILMAK BECERİ, DAYANIKLILIK VE AZIMSANMAYACAK KADAR ŞANS İSTER. BAZILARI BUNLARA DOĞUŞTAN SAHİPTİR.$NL;$NL;ŞANS, ELE AVUCA SIĞMAZ BİR NİTELİKTİR. ANTİK YUNANLILAR ONUN TANRILARIN TAKDİRİ OLDUĞUNA İNANIRDI. DEĞİLDİR. ELBETTE VARDIR AMA KAZANABİLECEĞİN BİR ŞEYDİR. TAŞLARI YERİNE KOYMAK VE KARŞILIK ALMA İHTİMALİNİ EN ÜST DÜZEYE ÇIKARMAK İÇİN HAZIRLIK VE ÖNGÖRÜ GEREKİR. FORTUNA’NIN LÜTFUNDAN ÇOK KART SAYMAYA BENZER.$NL;$NL;KUMARBAZ AVANTAJ DESTESİ BİR DESTEK DESTESİDİR. HERKES EKİBİN KAZANMASINA YARDIM EDEBİLİR AMA EKİBE BÜYÜK KAZANDIRMAK KUMARBAZ’IN İŞİDİR.",
["menu_st_spec_11"] = "ÖĞÜTÜCÜ",
["menu_st_spec_11_desc"] = "TİPİK BİR ÖĞÜTÜCÜ, ZOR DURUMLARI KONTROL ALTINA ALIP TERSİNE ÇEVİREBİLEN ÇALIŞKAN BİRİDİR.$NL;$NL;ÖĞÜTÜCÜ HER ZAMAN EN ÖNDE OLMAYA VE ACI ÇEKTİRMEYE DAYANIR. NE KADAR HASAR ALMIŞ OLURSA OLSUN DÜŞMANLARA HASAR VERDİĞİ İÇİN HAYATTA KALIR.",
["menu_st_spec_12_desc"] = "YAKUZA, DÜNYANIN EN KORKULAN SUÇ ÖRGÜTLERİNDEN BİRİDİR. NİNKYO İLKELERİNE GÖRE YÖNETİLEN VE OYABUN’UN LİDERLİK ETTİĞİ YAKUZA; KATI DAVRANIŞ KURALLARI, ÖRGÜTLÜ YAPISI VE TÜM VÜCUDU KAPLAYAN DÖVMELERİYLE TANINIR.$NL;$NL;TOPLUMUN DIŞINA İTİLMİŞ YAKUZA, KENDİ BAŞININ ÇARESİNE BAKMAYI BİLİR. NAZİK GÖRÜNSE DE HAFİFE ALINMAMALIDIR.",
["menu_st_spec_13"] = "ESKİ BAŞKAN",
["menu_st_spec_13_desc"] = "EX-PRESİDENTS, EN CÜRETKÂR SOYGUN EKİPLERİNDEN BİRİDİR. BÜYÜK RİSKLER ALAN SİLAH ARKADAŞLARIDIR. KENDİ ÖLÜMLÜLÜKLERİNDEN KORKMAMALARI ONLARI BİR ARAYA GETİRMİŞ VE BU KADAR BAŞARILI KILMIŞTIR.",
["menu_st_spec_14"] = "MANYAK",
["menu_st_spec_14_desc"] = "MANYAK AVANTAJ DESTESİ, DELİLİĞİN VE TEHLİKE ANINDA KÖTÜ İHTİMALLERE ASLA BOYUN EĞMEMENİN VÜCUT BULMUŞ HÂLİDİR. İLERİ ATILIP SÜREKLİ HASAR VEREREK SOYGUNCU ARKADAŞLARINA GEÇİCİ BİR KALKAN KAZANDIRIRSIN.",
["menu_st_spec_15"] = "ANARŞİST ",
["menu_st_spec_15_desc"] = "ANARŞİST, GELENEKSEL OTORİTENİN DAYATTIĞI KEYFÎ YASALARI TANIMAZ. KRALLAR, KRALİÇELER VE BAŞKANLAR ANARŞİST’İN ZİHNİNE HÜKMEDEMEZ. ÖZGÜRCE UÇ VE KENDİ KURALLARINI KOY; SLOGANI BUDUR. YERLEŞİK DOĞRULARA BOYUN EĞMEYİ REDDETMESİ, BAŞKALARININ GİDEMEDİĞİ YERLERE GİTMESİNİ SAĞLAR. ALIŞILMADIK TAKTİKLERLE ARALIKLARDAN SIZIP İMKÂNSIZ GÖRÜNEN HEDEFLERE ULAŞIR.",
["menu_st_spec_16"] = "MOTORCU",
["menu_st_spec_16_desc"] = "MOTOSİKLET ÇETELERİ TÜM DÜNYADA KORKU SALAR; BÜYÜK KULÜPLERİN ADINI HERKES BİLİR. MOTORCU OLMAK İÇİN SERT VE SADIK OLMALI, KULÜP KURALLARININ MUTLAK OLDUĞUNU BİLMELİSİN. MOTORCULAR ACIMASIZ VE ŞİDDET YANLISI OLMALARIYLA TANINIR; KARŞILARINA ÇIKMAYA CESARET EDENLERE MEYDAN OKUMAKTAN ASLA KORKMAZLAR.$NL;$NL;ARMANI TAKIP MOTOSİKLETİNE BİNDİĞİNDE HERKESE YÜZDE 1’E AİT OLDUĞUNU İLAN EDERSİN. TOPLUMUN KURALLARINA UYMAYI REDDEDEN, KANUN KAÇAĞI UNVANINI GURURLA TAŞIYAN YÜZDE 1’E. BİR MOTORCU İÇİN ÖNEMLİ OLAN YALNIZCA KULÜP ARKADAŞLARI VE MOTOSİKLETİDİR.",
["menu_st_spec_17"] = "SUÇ BARONU",
["menu_st_spec_17_desc"] = "SUÇ BARONU PATRONDUR; HER KAPRİSİNE UYULMASI GEREKEN BİR MUTLAK HÂKİM. AMA ÖNCE PARAYI KAZANMALISIN. PARAYI KAZANINCA GÜCÜ KAZANIRSIN. UNUTMA, BU DÜNYADA EMİR VEREN TEK ŞEY... CESARETTİR.",
["menu_st_spec_18"] = "KİRALIK KATİL",
["menu_st_spec_18_desc"] = "HER UYUŞTURUCU KARTELİNDE BİR KİRALIK KATİL ŞARTTIR. HER TÜR SORUNU SON DERECE ÖLÜMCÜL BİÇİMDE ÇÖZEN BİRİ. KİRALIK KATİL KAVGADAN ASLA KAÇMAZ; İŞİ TEREDDÜTSÜZ VE KORKUSUZCA BİTİRİR.",
["menu_st_spec_19"] = "STOACI",
["menu_st_spec_19_desc"] = "KIRILMAZ BİR KARARLILIK VE SÜKÛNET DUVARISIN. ZİHİN DİSİPLİNİ, STOACI’NIN BAŞKALARINI AĞLAYIP TİTREYEN BİR YIĞINA ÇEVİRECEK DURUMLARIN ÜSTESİNDEN GELMESİNİ SAĞLAR. BUDİST RAHİPLERDEN ÖĞRENİLEN NEFES TEKNİKLERİ VE FİZİKSEL TEPKİ KONTROLÜ, DÜŞMAN NE YAPARSA YAPSIN İŞİ BİTİRECEK KADAR AYAKTA KALMANI SAĞLAR.",
["menu_st_spec_1_desc"] = "CAPOREGİME OLARAK DA BİLİNEN EKİP LİDERİ, ORGANİZE BİR SUÇ ÖRGÜTÜNÜN BİR KOLUNUN BAŞIDIR. BİR GRUP ADAMA KOMUTA EDER VE DOĞRUDAN PATRONA VEYA PATRON YARDIMCISINA HESAP VERİR.$NL;$NL;SUÇ ÖRGÜTÜNÜN BİRİNİN İCABINA BAKMASI GEREKTİĞİNDE, EKİP LİDERİ VE ADAMLARI İŞİN YAPILMASINI SAĞLAR.",
["menu_st_spec_2"] = "KAS GÜCÜ",
["menu_st_spec_20"] = "İKİLİ EKİP",
["menu_st_spec_20_desc"] = "BAZILARINA GÖRE DENEYİMLER PAYLAŞTIKÇA GÜZELLEŞİR; PERFORMANS ARTIRICI AEROSOL AYGITLARINDA BİLE! SEVDİĞİN O ÖZEL SOYGUNCUYLA BANKA KASALARINI BOŞALTIP İŞ BİTİRİRKEN ARANIZDAKİ BAĞI GÜÇLENDİRECEK BİR ŞEY.",
["menu_st_spec_21"] = "BİLGİSAYAR KORSANI",
["menu_st_spec_21_desc"] = "KESKİN ZEKÂN VE EKİPMANINLA TEK DÜĞMEYE BASARAK HER GÜVENLİK SİSTEMİNİ DİZE GETİREBİLİRSİN. BİR KAMERA VEYA MUHAFIZ SENİ ASLA HAZIRLIKSIZ YAKALAYAMAZ. AMA İŞLER TERS GİDERSE DÜŞMAN İLETİŞİMİNE ZORLA GİRİP DİNLEYEN HERKESE KÖTÜ BİR SÜRPRİZ SUNMAN DA BİR O KADAR KOLAYDIR.",
["menu_st_spec_22"] = "SÜLÜK",
["menu_st_spec_22_desc"] = "SAVAŞTA SEÇİCİ BİR PARAZİTSİN; DÜŞMANLARINI TÜKETEREK KENDİNİ VE EKİP ARKADAŞLARINI GÜÇLENDİRİRSİN. AMA YALNIZCA DAYAK YİYEBİLEN BİR ET YIĞINI DEĞİLSİN. ACI ÇEKTİRMEYİ DE BİLİR, SALDIRGANLIĞINI EKİBİNİ GÜÇLENDİRMEK İÇİN KULLANIRSIN.  ",
["menu_st_spec_23"] = "TAKLİTÇİ",
["menu_st_spec_23_desc"] = "KUSURSUZ HAFIZASI VE GÖRDÜĞÜNÜ AYNEN UYGULAYAN REFLEKSLERİYLE TAKLİTÇİ, FİZİKSEL BİR HARİKADIR. HAREKETLERİ ÖNCEDEN SEZMEN SENİ ÖYLE ÇEVİK KILDI Kİ MERMİLERDEN KOLAYCA SIYRILABİLİR, HATTA ONLARI SEKTİREBİLİRSİN. DİĞER AVANTAJ DESTELERİNİ YAKINDAN İNCELEDİN; ARTIK KENDİ YETENEKLERİNİ GELİŞTİRMEK İÇİN ONLARIN TEMEL YETENEKLERİNİ TAKLİT EDEBİLİRSİN. TEKNİKLERİ BİR ARAYA GETİRİP HEM TANIDIK HEM SANA ÖZGÜ BİR TARZ YARAT. SENİ HIRSIZLIKLA SUÇLAYANLARA, TAKLİDİN EN İÇTEN İLTİFAT OLDUĞUNU HATIRLAT.",
["menu_st_spec_2_desc"] = "KAS GÜCÜ, MAFYA PATRONLARININ MESAJLARINI ŞİDDETLE İLETEN SERT ADAMDIR. HER SUÇ ÖRGÜTÜNÜN BELKEMİĞİDİR.$NL;$NL;BİRİNİ HIRPALAMAK, BACAK KIRMAK, KAFA EZMEK VEYA PATRONUN KİM OLDUĞUNU HATIRLATMAK GEREKTİĞİNDE KAS GÜCÜ ÇAĞRILIR.",
["menu_st_spec_3"] = "ZIRH USTASI",
["menu_st_spec_3_desc"] = "ZIRH USTALIĞI ESKİDEN ORDUDA BİR MESLEKTİ. ZIRH USTASININ İŞİ ZIRHLARIN BAKIMINI YAPMAK, ONLARI ONARMAK VE GELİŞTİRMEKTİR.$NL;$NL;KENDİNE SAYGISI OLAN HER SUÇ ÖRGÜTÜNÜN, ADAMLARININ İŞLERİNİ YAPMAK İÇİN GEREKEN KORUMAYA SAHİP OLMASINI SAĞLAYACAK BİRİNE İHTİYACI VARDIR.",
["menu_st_spec_4"] = "HAYDUT",
["menu_st_spec_4_desc"] = "HAYDUT; SİNSİ NUMARALAR ÇEVİREBİLEN, ÖLÜMCÜL GÜÇ KULLANABİLEN, GİZLİLİKTE USTA BİR SUÇLUDUR. ÇOK YÖNLÜ VE ALDATICI HAYDUT, YANKESİCİLİKTEN EV SOYGUNLARINA VE DOLANDIRICILIĞA KADAR HER TÜRLÜ İŞ İÇİN TUTULUR.$NL;$NL;HAYDUT’UN AYIRT EDİCİ ÖZELLİĞİ ÇOK YÖNLÜLÜĞÜDÜR. GÜÇ EKSİĞİNİ BECERİYLE KAPATIR.",
["menu_st_spec_5"] = "TETİKÇİ",
["menu_st_spec_5_desc"] = "TETİKÇİ, SUÇ DÜNYASINDAN GELEN, YAKIN VE UZAK ÇATIŞMADA USTA BİR PROFESYONEL KATİLDİR.$NL;$NL;SUÇ ÖRGÜTLERİ OTORİTELERİNİ KORUMAK, MİSİLLEME YAPMAK VEYA REKABETİ ORTADAN KALDIRMAK İÇİN SON ÇARE OLARAK BİR TETİKÇİ TUTAR.",
["menu_st_spec_6"] = "DÜZENBAZ",
["menu_st_spec_6_desc"] = "DÜZENBAZ ÇOK YÖNLÜ BİR SUÇLUDUR. BU TERİM SUÇUN KENDİSİ KADAR ESKİDİR.$NL;$NL;GERÇEKTEN DE DÜZENBAZ HER İŞTEN ANLAR AMA HİÇBİRİNİN USTASI DEĞİLDİR. GEÇİNMEK İÇİN ÇALAR, YALAN SÖYLER, HİLE YAPAR; GEREKEN HER TÜRLÜ DÜRÜST OLMAYAN VEYA YASA DIŞI İŞİ YAPAR.",
["menu_st_spec_7"] = "HIRSIZ",
["menu_st_spec_7_desc"] = "HIRSIZ’IN DOĞAL EL BECERİSİ YALNIZCA BİR YERE ZORLA GİRMEKTEN ÖTE FAYDALAR SAĞLAR. ÇEVİKLİĞİ SAYESİNDE KİLİTLERİ AÇAR, CESETLERİ TORBALAR VE ÇAĞRI CİHAZLARINA DAHA HIZLI CEVAP VERİR. ÇATIŞMADA VURULMASI DA DAHA ZORDUR. ARADAN ÇEKİLİP HAYATTA KALIR.$NL;$NL;BU FİZİKSEL KONDİSYON, HIRSIZ’A YÜKSEK ACI TOLERANSI VE YARALARI HIZLA ATLATMA YETENEĞİ DE VERİR.",
["menu_st_spec_8"] = "SIZMA UZMANI",
["menu_st_spec_8_desc"] = "SIZMA UZMANI; DÜŞMANLARI HAKKINDA BİLGİ EDİNMEK İSTEYEN BİR HÜKÜMET VEYA BÜYÜK SUÇ ÖRGÜTÜ YA DA RAKİPLERİNİN SANAYİ SIRLARINI ÖĞRENMEK İSTEYEN BİR ŞİRKET TARAFINDAN TUTULAN AJANDIR.$NL;$NL;SIZMA UZMANI, ÜSTÜNLÜK SAĞLAMAK İÇİN ÇEVREYİ KULLANMAYI BİLEN BİR YAKIN DÖVÜŞ UZMANIDIR.",
["menu_st_spec_9"] = "SOSYOPAT",
